import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import Shimmer from '../Shimmer';
import Error from '../Error';
import { Link } from 'react-router-dom';

const ProductListDetails = () => {
  const { id } = useParams();
  const [product, setProduct] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    async function getProductDetails() {
      try {
        setIsLoading(true);
        let res = await fetch(`https://fakestoreapi.in/api/products/${id}`);
        let data = await res.json();
        setProduct(data.product); // the API returns { product: { ... } }
      } catch (err) {
        setError("Failed to fetch product details.");
      } finally {
        setIsLoading(false);
      }
    }

    getProductDetails();
  }, [id]);

  if (isLoading) return <Shimmer />;
  if (error) return <Error message={error} />;
  if (!product) return <h5 className="text-danger text-center mt-5">Product not found</h5>;

  return (
    <div className="container mt-4">
      <Link className="btn btn-primary badge badge-danger" to="/products">
      Back to Products</Link>
      <div className="card shadow-lg rounded-4 p-4">
        <div className="row">
          <div className="col-md-6 text-center">
            <img src={product.image} alt="Product" className="img-fluid p-3" style={{ maxHeight: "400px" }} />
          </div>
          <div className="col-md-6">
            <h2 className="text-uppercase fw-bold">{product.brand}</h2>
            <h5 className="badge bg-warning text-dark fs-6 mb-2">{product.category}</h5>
            <h4 className="mb-3">{product.title}</h4>
            <h3 className="text-success fw-bold mb-4">₹{product.price}</h3>
            <p className="text-sm ">{product.description}</p>
            <button className="btn btn-primary btn-lg">Add to Cart</button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ProductListDetails;
